/**
 * getIndividualPerformance against resultat.schack.se's "Individuella resultat".
 *
 * The fixture holds stripped raw inputs and the official rows for a few
 * tournaments. It is generated by `pnpm perf:fixture --individual-results`
 * (scripts/perf-fixture.mjs) and frozen — this test is offline.
 */

import { getIndividualPerformance, type PlayerAt } from '../../src/utils/individualPerformance';
import type { MemberFIDERatingDTO, TournamentDto, TournamentRoundResultDto } from '../../src/types';
import fixture from '../fixtures/individual-results.json';

interface OfficialRow {
  memberId: number;
  name: string;
  sp: number;
  w: number;
  d: number;
  l: number;
  p: number;
  perf: number | null;
}

interface RawTournament {
  label: string;
  tournament: unknown;
  roundResults: Record<string, { roundNr: number; date: string; games: [number, number, number][] }[]>;
  ratings: { dated: Record<string, MemberFIDERatingDTO | null>; table: Record<string, MemberFIDERatingDTO | null> };
  official: OfficialRow[];
  notInApi: OfficialRow[];
}

function inputs(raw: RawTournament) {
  const roundResults = new Map<number, TournamentRoundResultDto[]>(
    Object.entries(raw.roundResults).map(([groupId, rows]) => [
      Number(groupId),
      rows.map((r) => ({
        roundNr: r.roundNr,
        date: r.date,
        games: r.games.map(([whiteId, blackId, result]) => ({ whiteId, blackId, result })),
      })) as TournamentRoundResultDto[],
    ])
  );
  // Ratings as the official site uses them: the list of the round's month — or
  // the current list for a round scheduled in a future month but already played
  // (the snapshot was fetched then) — else the results-table snapshot for
  // players the dated lookup lacks.
  const playerAt: PlayerAt = (id, date) => {
    const month = [`${date.slice(0, 7)}-01`, CURRENT_MONTH].sort()[0];
    const elo = raw.ratings.dated[`${id}@${month}`] ?? raw.ratings.table[id];
    return elo ? { elo } : undefined;
  };
  return { tournament: raw.tournament as TournamentDto, roundResults, playerAt };
}

const tournaments = fixture.tournaments as unknown as RawTournament[];
/** The rating list current when the fixture was fetched. */
const CURRENT_MONTH = `${fixture._meta.fetchedAt.slice(0, 7)}-01`;

describe.each(tournaments.map((t) => [t.label, t] as const))('%s', (_label, raw) => {
  const { tournament, roundResults, playerAt } = inputs(raw);
  const rows = getIndividualPerformance(tournament, roundResults, playerAt);
  const byPlayer = new Map(rows.map((r) => [r.playerId, r]));

  it('has one row per official player, and no others', () => {
    expect(rows.map((r) => r.playerId).sort((a, b) => a - b))
      .toEqual(raw.official.map((o) => o.memberId).sort((a, b) => a - b));
    for (const missing of raw.notInApi) expect(byPlayer.has(missing.memberId)).toBe(false);
  });

  it('matches every official row: SP, W/D/L, points and PERF', () => {
    const misses = raw.official.flatMap((o) => {
      const r = byPlayer.get(o.memberId);
      const got = r && { sp: r.games, w: r.won, d: r.drawn, l: r.lost, p: r.points, perf: r.performance };
      const want = { sp: o.sp, w: o.w, d: o.d, l: o.l, p: o.p, perf: o.perf };
      return JSON.stringify(got) === JSON.stringify(want)
        ? []
        : [`${o.name} [${o.memberId}]: official ${JSON.stringify(want)}, got ${JSON.stringify(got)}`];
    });
    expect(misses).toEqual([]);
  });

  it('orders rows like the official list (ties compared as sets)', () => {
    expect(rows.map((r) => r.performance)).toEqual(raw.official.map((o) => o.perf));
    const groupsOf = (list: { id: number; perf: number | null }[]) => {
      const m = new Map<number | null, Set<number>>();
      for (const { id, perf } of list) m.set(perf, (m.get(perf) ?? new Set()).add(id));
      return m;
    };
    expect(groupsOf(rows.map((r) => ({ id: r.playerId, perf: r.performance }))))
      .toEqual(groupsOf(raw.official.map((o) => ({ id: o.memberId, perf: o.perf }))));
  });
});

it('covers the cases the rules were derived from', () => {
  const official = tournaments.flatMap((t) => t.official);
  expect(official.length).toBeGreaterThanOrEqual(150);
  expect(official.some((o) => o.sp > o.w + o.d + o.l)).toBe(true); // walkovers / byes in SP only
  expect(official.some((o) => o.perf === null)).toBe(true);         // no rated opponent
  expect(tournaments.some((t) => Object.keys(t.roundResults).length > 1)).toBe(true);
});
